package postgresql

import (
	"context"
	"testing"

	"github.com/DATA-DOG/go-sqlmock"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/opskat/opskat/pkg/dbdriver"
)

// 新增行：给 GENERATED ALWAYS 列填了值时带 OVERRIDING SYSTEM VALUE（否则数据库拒绝显式值）；
// 没给它值的行、GENERATED BY DEFAULT / serial 列照常写；一列都没填的行整行取默认值。
func TestGridEditInsertsOverrideGeneratedAlwaysForPostgreSQL(t *testing.T) {
	session, mock := newMock(t)
	mock.ExpectQuery(columnsSQL).WithArgs("public", "users").
		WillReturnRows(sqlmock.NewRows([]string{"column_name", "data_type", "udt_name", "is_nullable", "column_default", "is_auto_increment", "is_identity_always"}).
			AddRow("id", "integer", "int4", "NO", nil, true, true).
			AddRow("seq", "integer", "int4", "NO", "nextval('s')", true, false).
			AddRow("name", "text", "text", "YES", nil, false, false))

	statements, err := session.GridEditStatements(context.Background(), "mydb", "public.users", dbdriver.GridEditRequest{
		Columns: []string{"id", "seq", "name"},
		Inserts: []dbdriver.GridInsert{
			{Values: []dbdriver.ColumnValue{{Column: "id", Value: "7"}, {Column: "name", Value: "a"}}},
			{Values: []dbdriver.ColumnValue{{Column: "seq", Value: "3"}, {Column: "name", Value: "b"}}},
			{},
		},
	})
	require.NoError(t, err)
	assert.Equal(t, []string{
		`INSERT INTO "public"."users" ("id", "name") OVERRIDING SYSTEM VALUE VALUES ('7', 'a');`,
		`INSERT INTO "public"."users" ("seq", "name") VALUES ('3', 'b');`,
		`INSERT INTO "public"."users" DEFAULT VALUES;`,
	}, statements.Inserts)
	require.NoError(t, mock.ExpectationsWereMet())
}

// 有主键时按主键定位，语句不另加限制；没有主键时用 (tableoid, ctid) 把全列匹配到的几行收敛成
// 物理上的一行：ctid 只在单个分区 / 子表内唯一，带上 tableoid 才不会改到别的分区里 ctid 相同的行。
func TestGridEditLocatesRowsForPostgreSQL(t *testing.T) {
	session, mock := newMock(t)
	ctx := context.Background()
	columns := func(table string, names ...string) {
		rows := sqlmock.NewRows([]string{"column_name", "data_type", "udt_name", "is_nullable", "column_default"})
		for _, name := range names {
			rows.AddRow(name, "text", "text", "YES", nil)
		}
		mock.ExpectQuery(columnsSQL).WithArgs("public", table).WillReturnRows(rows)
	}

	columns("t", "id", "n")
	statements, err := session.GridEditStatements(ctx, "mydb", "t", dbdriver.GridEditRequest{
		Columns: []string{"id", "n"}, PrimaryKeys: []string{"id"},
		Updates: []dbdriver.GridUpdate{{Row: map[string]any{"id": float64(7), "n": "old"}, Set: []dbdriver.ColumnValue{{Column: "n", Value: "x"}}}},
	})
	require.NoError(t, err)
	assert.Equal(t, []string{`UPDATE "t" SET "n" = 'x' WHERE "id" = '7';`}, statements.Updates)

	columns("t", "id", "n")
	statements, err = session.GridEditStatements(ctx, "mydb", "t", dbdriver.GridEditRequest{
		Columns: []string{"id", "n"},
		Updates: []dbdriver.GridUpdate{{Row: map[string]any{"id": float64(7), "n": nil}, Set: []dbdriver.ColumnValue{{Column: "n", Value: "x"}}}},
		Deletes: []map[string]any{{"id": float64(7), "n": "old"}},
	})
	require.NoError(t, err)
	assert.Equal(t, []string{`UPDATE "t" SET "n" = 'x' WHERE (tableoid, ctid) = (SELECT tableoid, ctid FROM "t" WHERE "id" = '7' AND "n" IS NULL LIMIT 1);`}, statements.Updates)
	assert.Equal(t, []string{`DELETE FROM "t" WHERE (tableoid, ctid) = (SELECT tableoid, ctid FROM "t" WHERE "id" = '7' AND "n" = 'old' LIMIT 1);`}, statements.Deletes)

	columns(`audit"logs`, `id"part`, "name")
	statements, err = session.GridEditStatements(ctx, "mydb", `audit"logs`, dbdriver.GridEditRequest{
		Columns: []string{`id"part`, "name"}, PrimaryKeys: []string{`id"part`},
		Deletes: []map[string]any{{`id"part`: float64(7), "name": "alice"}},
	})
	require.NoError(t, err)
	assert.Equal(t, []string{`DELETE FROM "audit""logs" WHERE "id""part" = '7';`}, statements.Deletes)
	require.NoError(t, mock.ExpectationsWereMet())
}
